/* the page current: rail comet travels during the first half of the shared
   period (site ms-bus-flow geometry), parked dark the second half */
@keyframes ilm-bus-flow {
  0% { top: 2.2rem; opacity: 0; }
  6% { opacity: 1; }
  44% { opacity: 1; }
  50% { top: calc(100% - 1.8rem - 64px); opacity: 0; }
  100% { top: calc(100% - 1.8rem - 64px); opacity: 0; }
}
/* divider sweep: a glint crosses the title rule (site ms-glint look);
   both ends park off-path so the loop never blinks */
@keyframes ilm-rule-flow {
  0% { background-position: -24px 50%, 0 0, 0 50%; }
  16% { background-position: calc(100% + 24px) 50%, 0 0, 0 50%; }
  100% { background-position: calc(100% + 24px) 50%, 0 0, 0 50%; }
}
/* spur glint: darts across the connector stub into the widget
   (the stub now carries three layers: glint, junction node, line) */
@keyframes ilm-spur-flow {
  0% { background-position: -14px 50%, 0 0, 3.5px 50%; }
  7% { background-position: calc(100% + 14px) 50%, 0 0, 3.5px 50%; }
  100% { background-position: calc(100% + 14px) 50%, 0 0, 3.5px 50%; }
}

/* via ping: flares as the current passes (site --ping drop-shadow) */
